  function mount(){var w=document.getElementById('exHomeWrap');if(!w||w.querySelector('.demo-functions'))return;var s=document.createElement('section');s.className='demo-functions';s.setAttribute('aria-label','平台全部功能入口');s.innerHTML='<div class="demo-functions-head"><h2>探索红色记忆</h2><p>从一段故事开始，走近红色记忆</p></div><div class="demo-function-grid">'+entries.map(function(e){return '<button class="demo-function" data-demo-feature="'+e[3]+'"><span class="df-symbol" aria-hidden="true">'+e[0]+'</span><span class="df-arrow">↗</span><strong>'+e[1]+'</strong><small>'+e[2]+'</small></button>'}).join('')+'</div><div class="demo-footnote"><span>免费展示版 · 史料内容仍待第二人复核</span><span>参观无需登录 · 收藏与进度保存在此浏览器</span></div><p class="demo-photo-credit">封面背景：遵义会议会址现代照片 · N509FZ / Wikimedia Commons / CC BY-SA 4.0 · 图像经渐变叠色处理</p>';w.appendChild(s)}
  new MutationObserver(mount).observe(document.getElementById('exHomeWrap'),{childList:true});mount();
  function click(sel){var b=document.querySelector(sel);if(b)b.click()}
  document.addEventListener('click',function(e){var b=e.target.closest('[data-demo-feature]');if(!b)return;var f=b.dataset.demoFeature;if(f==='tour'){click('[data-ex-ch="ch-01"]');return}if(f==='story'){click('[data-ex-intro]');click('[data-ex-story]');return}if(f==='atlas'){click('#viewSeg [data-view="atlas"]');return}click('#viewSeg [data-view="topic"]');if(f==='graph'){if(matchMedia('(max-width:820px)').matches)click('#mNav [data-m="detail"]');click('[data-tab="graph"]')}if(f==='ai'){if(matchMedia('(max-width:820px)').matches)click('#mNav [data-m="detail"]');click('[data-tab="ai"]')}if(f==='map'){var mb=document.querySelector('[data-mob="map"], [data-m="map"]');if(mb)mb.click()}});
